# Run from the package root after data-raw/dat/build_dat_exposure.R:  Rscript data-raw/qa/71_dat_exposure_section.R
# Writes the section "DAT columns, tract and block-group tables" of data-raw/known_issues.md (between <!-- dat-exposure:start --> and <!-- dat-exposure:end -->): the rule, the counts of footprint polygons, zones, rows and points, from
# data-raw/dat/fetch/exposure_summary_tables.rds (saved by the build) and the data in data/. Also writes rows dat_* in data-raw/readme/numbers.csv.
suppressMessages({library(sf); library(dplyr)}); source("data-raw/qa/helpers.R"); for (f in list.files("data", pattern = "[.]rda$", full.names = TRUE)) load(f)
D <- readRDS("data-raw/dat/fetch/exposure_summary_tables.rds"); f0 <- function(x) formatC(x, format = "d", big.mark = ","); pc <- function(x, d = 1) sprintf(paste0("%.", d, "f%%"), 100 * x)
md <- function(df) { df[] <- lapply(df, as.character); paste(c(paste0("| ", paste(names(df), collapse = " | "), " |"), paste0("|", paste(rep("---", ncol(df)), collapse = "|"), "|"), apply(df, 1, function(r) paste0("| ", paste(r, collapse = " | "), " |"))), collapse = "\n") }
d <- tornado_exposure; fp <- D$footprint; lk <- tornado_dat_link; ln <- d$dat_linked
oth <- D$other_efscale; oth_t <- data.frame(`efscale of a touching polygon that is not used` = names(oth), Pairs = f0(as.integer(oth)), check.names = FALSE)
pt_cols <- grep("^dat_points_", names(d), value = TRUE); in_rows <- sum(d[ln, pt_cols])
by_rating <- data.frame(Rating = paste0("EF", 0:5), `Tornado-ZCTA rows with area` = f0(vapply(0:5, function(j) sum(d[[paste0("dat_area_share_ef", j)]] > 0, na.rm = TRUE), 0)), `Residents` = f0(round(vapply(0:5, function(j) sum(d[[paste0("dat_pop_ef", j)]], na.rm = TRUE), 0))), check.names = FALSE)
tab_rows <- data.frame(Table = c("`tornado_exposure`", "`dat_exposure_tract`", "`dat_exposure_blockgroup`"), Rows = f0(c(nrow(d), nrow(dat_exposure_tract), nrow(dat_exposure_blockgroup))), Tornadoes = f0(c(length(unique(d$tornado_id)), length(unique(dat_exposure_tract$tornado_id)), length(unique(dat_exposure_blockgroup$tornado_id)))), check.names = FALSE)
bd <- d$boundary_dist_km[!d$spc_exposed]
txt <- c("<!-- dat-exposure:start -->", "## DAT columns, tract and block-group tables", "",
 paste0("**Rule.** A DAT polygon belongs to a tornado when a DAT line linked to the tornado (`tornado_dat_link`) touches it (`dat_polygon_line_link`, `line_share_in_polygon` above 0: a zero test, not a cutoff; the share is the length of the line inside the polygon over the length of the line, computed on the polygon repaired with `st_make_valid()` where invalid). Only polygons rated EF0 to EF5 are used; a polygon with any other `efscale` stays in `dat_polygons` and is not used. A polygon with no date (", f0(D$polygons_no_date), " of ", f0(nrow(dat_polygons)), ") is never linked, and a polygon with an empty geometry (", f0(D$polygons_empty), ") touches nothing; both stay in `dat_polygons`. The rule is the same for every tornado and has no parameter."), "",
 paste0("**Counts.** ", f0(fp[["pairs_touching"]]), " tornado-polygon pairs touch a linked line: ", f0(fp[["pairs_ef0_ef5"]]), " are rated EF0 to EF5 (", f0(fp[["polygons_used"]]), " polygons, ", f0(fp[["tornadoes_with_footprint"]]), " tornadoes) and ", f0(fp[["pairs_other_efscale"]]), " have another `efscale` (", f0(fp[["polygons_other_touching"]]), " polygons; ", f0(D$polygons_other_total), " of the ", f0(nrow(dat_polygons)), " polygons in `dat_polygons` have an `efscale` other than EF0 to EF5):"), "", md(oth_t), "",
 paste0("**Zones.** The polygons of different ratings overlap, so each tornado's footprint is cut into ", f0(D$zones[["zones"]]), " zones by the highest rating that covers each part (a zone is the union of the polygons of one rating minus the union of the polygons rated higher); the zones do not overlap, so their areas add up to the area of the union and each part is counted once. ", f0(D$zones[["polygons_repaired"]]), " polygons were invalid and are repaired with `st_make_valid()` for this computation only (the shipped polygons are not repaired)."), "",
 paste0("**Footprints with no ZCTA row.** ", f0(fp[["tornadoes_with_footprint"]]), " tornadoes have a footprint; ", f0(length(unique(d$tornado_id[d$dat_exposed %in% TRUE]))), " of them have at least one ZCTA with polygon land. The other ", f0(fp[["tornadoes_with_footprint"]] - length(unique(d$tornado_id[d$dat_exposed %in% TRUE]))), " have zones that cover no land of any ZCTA of their boundary year (areas the ZCTA files do not cover); ", f0(length(setdiff(unique(dat_exposure_tract$tornado_id), unique(d$tornado_id[d$dat_exposed %in% TRUE])))), " of those have rows in `dat_exposure_tract` and `dat_exposure_blockgroup`, and ", f0(fp[["tornadoes_with_footprint"]] - length(unique(dat_exposure_tract$tornado_id))), " have no row in any table (the zones cover no land)."), "",
 paste0("**Rows.** ", f0(D$rows[["spc_rows"]]), " rows are exposed by the SPC line; the linked polygons cover land in ", f0(D$rows[["dat_exposed_rows"]]), " tornado-ZCTA pairs, ", f0(D$rows[["both"]]), " of them also exposed by the line and ", f0(D$rows[["dat_only_rows"]]), " only by the polygons (`spc_exposed` `FALSE`; ", f0(length(unique(d$tornado_id[!d$spc_exposed]))), " tornadoes; the distance from the SPC line to their boundary has a median of ", sprintf("%.2f", median(bd)), " km, a 90th percentile of ", sprintf("%.2f", quantile(bd, .9)), " km and a maximum of ", sprintf("%.2f", max(bd)), " km). ", f0(sum(ln & !d$dat_exposed)), " rows of linked tornadoes are exposed only by the line (`dat_exposed` `FALSE`, area and residents 0). Rows and tornadoes of the three tables:"), "", md(tab_rows), "",
 paste0("**DAT-only rows far from the SPC line.** Of the ", f0(sum(!d$spc_exposed)), " DAT-only rows (`spc_exposed` `FALSE` and `dat_exposed` `TRUE`) in ", f0(length(unique(d$tornado_id[!d$spc_exposed]))), " tornadoes, for ", f0(length(unique(d$tornado_id[!d$spc_exposed])) - length(unique(d$tornado_id[!d$spc_exposed & d$boundary_dist_km > 5]))), " tornadoes every such row lies within 5 km of the SPC line (`boundary_dist_km`); the others are farther: ", f0(sum(!d$spc_exposed & d$boundary_dist_km > 5)), " rows (", f0(length(unique(d$tornado_id[!d$spc_exposed & d$boundary_dist_km > 5]))), " tornadoes) beyond 5 km, ", f0(sum(!d$spc_exposed & d$boundary_dist_km > 25)), " (", f0(length(unique(d$tornado_id[!d$spc_exposed & d$boundary_dist_km > 25]))), ") beyond 25 km and ", f0(sum(!d$spc_exposed & d$boundary_dist_km > 100)), " (", f0(length(unique(d$tornado_id[!d$spc_exposed & d$boundary_dist_km > 100]))), ") beyond 100 km, the farthest ", sprintf("%.2f", max(bd)), " km. These are probably wrong links or surveys of another tornado. No cutoff is applied: 5, 25 and 100 km are descriptive values, not recommendations, and `dat_link_dist_km` (the largest one-sided distance among the tornado's linked lines, from `tornado_dat_link`; `NA` where `dat_linked` is `FALSE`) and `boundary_dist_km` can be used to filter."), "",
 paste0("**By rating** (a part of the footprint is given the highest rating that covers it):"), "", md(by_rating), "",
 paste0("**Residents.** ", f0(round(sum(d$dat_pop_affected, na.rm = TRUE))), " residents are in the covered land of the rows of `tornado_exposure`; ", f0(round(D$residents_in_zctas_without_area)), " more reside in blocks assigned to a ZCTA that has no row for the tornado, and ", f0(round(D$residents_no_zcta)), " in blocks assigned to no ZCTA (they appear in the tract and block-group tables). The share of the land of a block covered by a zone is at most ", format(D$blocks[["largest_share"]], digits = 12), " and no share is capped."), "",
 paste0("**Damage points.** ", f0(in_rows), " damage-point counts (a point counts once for each tornado within a day) are in the rows of linked tornadoes; the counts cover only the ZCTAs, tracts and block groups that have a row for the tornado. Points are counted by `efscale` as entered (`EF0` to `EF5`, `EFU`, `TSTM/Wind`, and all other values or none in `dat_points_other`). A point dated within a day of a tornado can belong to another tornado: `other_tornadoes_in_zcta_within_a_day` counts the other SPC tornadoes whose line crosses the ZCTA within a day."), "",
 "<!-- dat-exposure:end -->")
kl <- readLines("data-raw/known_issues.md"); a <- grep("<!-- dat-exposure:start -->", kl, fixed = TRUE); b <- grep("<!-- dat-exposure:end -->", kl, fixed = TRUE)
kl <- if (length(a) && length(b)) c(kl[seq_len(a - 1)], txt, kl[-seq_len(b)]) else append(kl, c(txt, ""), after = grep("<!-- dat:start -->", kl)[1] - 1)
writeLines(kl, "data-raw/known_issues.md"); cat(txt, sep = "\n")
nm <- c(dat_footprint_polygons_used = fp[["polygons_used"]], dat_footprint_polygons_other = fp[["polygons_other_touching"]], dat_polygons_no_date = D$polygons_no_date, dat_footprint_tornadoes = fp[["tornadoes_with_footprint"]], dat_only_rows = D$rows[["dat_only_rows"]])
f <- "data-raw/readme/numbers.csv"; n <- read.csv(f, stringsAsFactors = FALSE); n <- n[!n$name %in% names(nm), ]; write.csv(rbind(n, data.frame(name = names(nm), value = unname(nm), source = "71")), f, row.names = FALSE)
